import numpy as np
from collections import Counter

def read_xyz(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0]); els=[]; pos=[]
    for ln in lines[2:2+n]:
        p = ln.split(); els.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return els, np.array(pos)

els, pos = read_xyz('initial.xyz')
ir = pos[els.index('Ir')]
zn = pos[els.index('Zn')]
d_ir = np.linalg.norm(pos-ir, axis=1)
print("Ir coordination (dist<2.7):")
for e,p,d in sorted(zip(els,pos,d_ir), key=lambda t:t[2]):
    if d<2.7 and e!='Ir':
        print(f"  {e:2s} {d:.3f}")
print("Ir-Zn:", np.linalg.norm(ir-zn))
# min H-H and heavy-heavy distances excluding bound pairs (rough check)
heavy = [i for i,e in enumerate(els) if e!='H']
mind=10; pair=None
for i in range(len(heavy)):
    for j in range(i+1,len(heavy)):
        a,b=heavy[i],heavy[j]
        dd=np.linalg.norm(pos[a]-pos[b])
        if dd<mind: mind=dd; pair=(els[a],a,els[b],b)
print("min heavy-heavy distance:", round(mind,3), pair)
H = [i for i,e in enumerate(els) if e=='H']
mindh=10; pairh=None
for i in range(len(H)):
    for j in range(i+1,len(H)):
        dd=np.linalg.norm(pos[H[i]]-pos[H[j]])
        if dd<mindh: mindh=dd; pairh=(H[i],H[j])
print("min H-H distance:", round(mindh,3), pairh)
